import AppKit
import TroveCore

/// Osserva NSPasteboard (polling di changeCount) e salva ogni nuova copia.
@MainActor
final class ClipboardMonitor {
    private let store: Store
    private let onChange: (Int64, Bool) -> Void
    private var lastChange = NSPasteboard.general.changeCount
    private var timer: Timer?

    /// Tipi marcati da password manager & co. (nspasteboard.org): mai salvati.
    static let ignoredTypes: Set<String> = [
        "org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "org.nspasteboard.AutoGeneratedType",
        "com.agilebits.onepassword", "de.petermaurer.TransientPasteboardType",
    ]

    init(store: Store, onChange: @escaping (_ id: Int64, _ isNew: Bool) -> Void) {
        self.store = store
        self.onChange = onChange
    }

    func start() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.4, repeats: true) { [weak self] _ in
            MainActor.assumeIsolated { self?.poll() }
        }
    }

    /// Da chiamare dopo aver scritto noi sul pasteboard, per non ricatturarlo.
    func skipCurrent() { lastChange = NSPasteboard.general.changeCount }

    private func poll() {
        let pb = NSPasteboard.general
        guard pb.changeCount != lastChange else { return }
        lastChange = pb.changeCount
        let types = Set((pb.types ?? []).map(\.rawValue))
        guard !types.isEmpty, types.isDisjoint(with: Self.ignoredTypes) else { return }
        let front = NSWorkspace.shared.frontmostApplication
        guard front?.bundleIdentifier != Bundle.main.bundleIdentifier else { return }
        guard let capture = Capture(pb) else { return }
        let app = front?.localizedName, bundle = front?.bundleIdentifier, store = store, onChange = onChange
        Task.detached(priority: .utility) {
            guard let item = capture.makeItem(store: store, app: app, bundle: bundle) else { return }
            let existed = store.get(byHash: item.hash) != nil
            guard let id = try? store.insert(item) else { return }
            await MainActor.run { onChange(id, !existed) }
        }
    }
}

/// Snapshot dei dati letti dal pasteboard sul main thread; la conversione pesante avviene fuori.
struct Capture: @unchecked Sendable {
    var string: String?
    var rtf: Data?
    var html: String?
    var image: Data?
    var files: [URL] = []

    init?(_ pb: NSPasteboard) {
        files = (pb.readObjects(forClasses: [NSURL.self], options: [.urlReadingFileURLsOnly: true]) as? [URL]) ?? []
        string = pb.string(forType: .string)
        rtf = pb.data(forType: .rtf)
        html = pb.string(forType: .html)
        if files.isEmpty { image = pb.data(forType: .png) ?? pb.data(forType: .tiff) }
        if files.isEmpty, image == nil, (string ?? "").trimmingCharacters(in: .whitespacesAndNewlines).isEmpty { return nil }
    }

    func makeItem(store: Store, app: String?, bundle: String?) -> ClipItem? {
        if !files.isEmpty {
            let paths = files.map(\.path)
            return ClipItem(kind: .file, text: files.map(\.lastPathComponent).joined(separator: "\n"), filePaths: paths,
                            sourceApp: app, sourceBundle: bundle, hash: Classifier.hash(Data(paths.joined(separator: "\n").utf8)))
        }
        if let s = string, !s.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty {
            var kind = Classifier.kind(forText: s)
            if kind == .text, rtf != nil || html != nil { kind = .richText }
            return ClipItem(kind: kind, text: s, rtf: kind == .richText ? rtf : nil, html: kind == .richText ? html : nil,
                            sourceApp: app, sourceBundle: bundle, hash: Classifier.hash(Data(s.utf8) + (rtf ?? Data())))
        }
        if let raw = image, let rep = NSBitmapImageRep(data: raw), let png = rep.representation(using: .png, properties: [:]) {
            let h = Classifier.hash(png)
            let name = h + ".png"
            let url = store.blobsDir.appendingPathComponent(name)
            if !FileManager.default.fileExists(atPath: url.path) { try? png.write(to: url) }
            return ClipItem(kind: .image, text: "\(rep.pixelsWide)×\(rep.pixelsHigh)", blobPath: name,
                            sourceApp: app, sourceBundle: bundle, hash: h)
        }
        return nil
    }
}
